const labels={poolXg:'Oyuncuların hücum havuzu',poolCreation:'Pas / fırsat üretimi',finishingQuality:'Bitiricilik (xGOT − xG)',opponentDefense:'Rakip oyuncuların savunması',
 opponentKeeper:'Rakip kalecilerin katkısı',scoringConcentration:'Gol tehdidinin yoğunlaşması',continuity:'Süre dağılımının sürekliliği',
 encounteredOpponentAttack:'Karşılaşılan oyuncuların hücumu',encounteredOpponentDefense:'Karşılaşılan oyuncuların savunması',sharedOpponentOverlap:'Ortak rakip oyuncu örtüşmesi',
 historyFraction:'Geçmişin güncelliği / derinliği',missingFraction:'Eksik ölçüm oranı'};
export function graphPredictionHtml(training,{esc,number,pct}){
 const g=training?.playerGraph;if(!g)return '';
 const b=g.comparison?.test.baseline,a=g.comparison?.test.graph,c=g.targetCoverage,effect=g.targetPrediction;
 const tag=g.active?g.status==='experimental'?'DENEYSEL AĞ MODELİ':'OYUNCU AĞI ETKİN':'TAKIM MODELİ';
 return `<div class="graph-prediction ${g.status==='experimental'?'experimental':''}" id="graph-prediction"><div class="card-title"><h3>Oyuncu ağından skor hesabına</h3><span class="tag">${tag}</span></div><p>${esc(g.reason)}</p><p class="inline-note">Oyuncu → geçmiş maç → rakip oyuncular → onların geçmiş maçları üzerinden ${g.featureNames.length} girdi öğrenilir. Bu maç için ${g.targetEvidence?.playerCount??0} oyuncu ve ${g.targetEvidence?.matchCount??0} maçlık kanıt işlendi. Hedef maçın sonucu ve sonradan görülen gerçek ilk 11’i bu katmana verilmez.</p>${effect?`<p class="inline-note">Öğrenilmiş takım tabanı: <b>${number(effect.baseline.home,2)} – ${number(effect.baseline.away,2)}</b> gol yoğunluğu. Seçilen model: <b>${number(effect.selected.home,2)} – ${number(effect.selected.away,2)}</b>. Sonraki oyuncu/H2H senaryoları bu tabanı ayrıca günceller.</p>`:''}${b&&a?`<details><summary>Takım modeli ve oyuncu ağı · ${a.sampleSize} test maçı</summary><div class="table-wrap"><table><thead><tr><th>İÇ TEST</th><th>ÖĞRENİLMİŞ TAKIM MODELİ</th><th>OYUNCU AĞI MODELİ</th></tr></thead><tbody><tr><td>Tam skor isabeti</td><td>${pct(b.exactScoreAccuracy)}</td><td>${pct(a.exactScoreAccuracy)}</td></tr><tr><td>1X2 isabeti</td><td>${pct(b.accuracy)}</td><td>${pct(a.accuracy)}</td></tr><tr><td>Skor log kaybı · düşük daha iyi</td><td>${number(b.pairedCountNll,3)}</td><td>${number(a.pairedCountNll,3)}</td></tr><tr><td>1X2 log kaybı · düşük daha iyi</td><td>${number(b.logLoss,3)}</td><td>${number(a.logLoss,3)}</td></tr></tbody></table></div><p class="inline-note">Otomatik seçim ayrı doğrulama bölümüne dayanır: skor log kaybında en az 0,003 iyileşme ve tam skor isabetinde düşüş olmaması gerekir. Buradaki test sonuçları seçimde kullanılmaz. Aynı arşiv üzerinde geliştirilen zaman sıralı iç testtir; gelecek maçlarda kesin skor garantisi değildir.</p></details>`:''}<details><summary>12 ağ girdisi ve veri kapsamı</summary><p class="inline-note">Hedef ligden önceki maçlar kullanılır. Az dakikalı oyuncular küçültülür; eski maçların ağırlığı azalır. Girdiler ölçeklidir; doğrudan gol olasılığı değildir. “—” eksik ölçümdür; modelde nötr girdi ve ayrıca eksiklik göstergesi kullanılır.</p><div class="table-wrap"><table><thead><tr><th>GİRDİ</th><th>EV</th><th>DEPLASMAN</th></tr></thead><tbody>${g.featureNames.map((name,i)=>`<tr><td>${esc(labels[name]??name)}</td>${['home','away'].map(side=>{const missing=i<10&&g.targetEvidence?.[side]?.metricValues?.[name]==null;return `<td>${missing?'—':number(g.targetFeatures?.[side]?.[i],3)}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div><p class="inline-note">Takım geçmişi: ${c?.home?.historyGames??0} / ${c?.away?.historyGames??0} maç. Dakika kapsamı: ${pct(c?.home?.minuteCoverage)} / ${pct(c?.away?.minuteCoverage)}. Eksik girdi: ${pct(c?.home?.missingFraction)} / ${pct(c?.away?.missingFraction)}.</p></details></div>`;
}
